package ops

// opDocs holds each operation's description: docxdriver 0.5.2's doc
// comments where the operation is its, in the contract's names.
var opDocs = map[string]string{
	"equation.replace":               "Replace one current equation with the LaTeX `latex`, without matching its reconstructed LaTeX. Tracked: the old equation deleted, the new one inserted. Direct: replaced.",
	"equation.delete":                "Delete one current equation while preserving the surrounding paragraph. Tracked: a tracked deletion. Direct: removed.",
	"text.replace":                   "Tracked: w:del / w:ins (the author's own pending insertion is edited in place). Direct: replaced, no revision.",
	"text.revise":                    "Several exact replacements inside one bounded scope: the paragraph `at`, the unique `within` span (in `at`, or anywhere in the body when `at` is omitted), or the whole body. Every edit resolves against the scope as it stands when this operation starts. Tracked: w:del / w:ins per edit. Direct: replaced, no revision.",
	"paragraph.replace":              "Tracked: old content deleted, new inserted. Direct: replaced, no revision.",
	"table.insert":                   "A `rows` × `columns` grid of new cells. `cells` fills them row by row with the inline content `paragraph.insert`'s `html` accepts; missing trailing rows and cells stay empty. With `as`, cell row N column M is the paragraph alias `$<as>_rNcM` for later operations. Tracked: an inserted table (every row w:trPr/w:ins, cell content w:ins); refused as the last block of a table cell. Direct: inserted, no revision.",
	"table.format":                   "Tracked: w:tblPrChange. Direct: applied, no revision.",
	"row.format":                     "Tracked: w:trPrChange. Direct: applied, no revision.",
	"cell.format":                    "Tracked: w:tcPrChange. Direct: applied, no revision.",
	"text.format":                    "Tracked: w:rPrChange. Direct: applied, no revision.",
	"paragraph.format":               "Tracked: w:pPrChange. Direct: applied, no revision.",
	"list.set":                       "Assign selected paragraphs to a new or existing list. `remove` explicitly suppresses inherited numbering. Tracked: w:pPrChange; rejecting it also removes the list definitions it added once nothing refers to them (definitions the input already left unreferenced stay). Direct: applied, no revision.",
	"paragraph.insert":               "One paragraph, or with a list `html`, one per item in list order. Each `html` value is one paragraph: either one block element, `<p>` or `<h1>`..`<h6>` as read shows it, whose style (the heading's tag, `data-style` or `class`) and paragraph CSS become the new paragraph's properties (its `id`, list marker and revision attributes, and an equation's `data-ref`, are ignored), or bare inline content, which is the content alone. Two block elements in one value, or a block element inside inline content, are refused: one paragraph per html value; use the list form for several. With `as`, a single paragraph is `$<as>`; for a list, `$<as>` is the group (expanded in paragraph lists, its first or last paragraph as an insert anchor) and item N is `$<as>_N`. Without `style`, a new paragraph takes the paragraph properties of a paragraph anchor (style, numbering, indents, spacing; not its mark's run properties, section properties or pending changes), as Word's Enter does: inserted into a list it is a list item. After a paragraph whose style names a different next style (a heading), it takes that style instead. Tracked: inserted content and paragraph mark; reject-all removes the paragraph. Direct: inserted, no revision.",
	"paragraph.delete":               "Tracked: content and paragraph mark deleted; accept-all leaves the following paragraph's id and properties as they were. A paragraph whose mark cannot join forward (the last of the body, one before a table, one ending a section) takes the previous paragraph's mark instead, as Word does: it gets that paragraph's properties (its own in a pPrChange) and keeps its section properties, and accept-all leaves the previous paragraph, with its id, in its place. Where no previous paragraph can join (a table or another author's mark revision before it) it is left empty. Direct: the same edit accepted, no revision.",
	"section.set_margins":            "Tracked: w:sectPrChange. Direct: applied, no revision.",
	"section.set_boundary":           "Selective section-property edits. Dimensions are points; omitted fields preserve source. Refused in track mode: Word records no revision for adding or removing a section break. Direct only.",
	"section.set_layout":             "Tracked: w:sectPrChange. Direct: applied, no revision.",
	"section.set_first_page":         "Tracked: w:sectPrChange. Direct: applied, no revision.",
	"document.set_even_odd_headers":  "Refused in track mode: a document setting (settings.xml) Word records no revision for. Direct only.",
	"header.set":                     "Tracked: the old content a tracked deletion and the new a tracked insertion (simple fields written as complex field runs); a new header's part and reference cannot be tracked, so reject-all leaves it empty. `kind: first` records titlePg in a w:sectPrChange; `kind: even` is refused while even/odd headers are off. Direct: replaced, no revision.",
	"footer.set":                     "Tracked and direct as `header.set`.",
	"header.delete":                  "Tracked: the content becomes a tracked deletion and the (then empty) header stays referenced; refused after section 1, where removing a reference changes inheritance. Direct: the reference is removed.",
	"footer.delete":                  "Tracked and direct as `header.delete`.",
	"comment.add":                    "Applied directly in both change modes: Word does not track comments.",
	"comment.reply":                  "Applied directly in both change modes: Word does not track comments.",
	"comment.set_status":             "Applied directly in both change modes: Word does not track comments.",
	"comment.delete":                 "Applied directly in both change modes: Word does not track comments.",
	"bookmark.add":                   "Bookmark the paragraph `at`: its whole content, or the `select` span. Applied directly in both change modes (Word does not track bookmarks). Body paragraphs only.",
	"bookmark.rename":                "Rename a body bookmark; `name` (the new name) follows the add rules. Applied directly in both change modes (Word does not track bookmarks).",
	"bookmark.move":                  "Re-anchor a body bookmark, keeping its name and `w:id`. Applied directly in both change modes (Word does not track bookmarks).",
	"bookmark.delete":                "Remove a body bookmark's start and end markers; the text stays. Applied directly in both change modes (Word does not track bookmarks).",
	"revision.convert_to_formatting": "Turn tracked changes into amendment formatting (37 CFR 1.121): an insertion's text stays, underlined; a deletion's text comes back, struck through; no revision is left. A deleted paragraph mark stays (the paragraph's struck text keeps its own line); an inserted paragraph stays with its text underlined; inserted and deleted table rows stay, their text underlined or struck. Formatting, table and section property changes have no amendment form and are accepted. Moves convert as deletion (source) and insertion (destination). Where struck and underlined text meet with a word character on both sides (a replaced word, whose redline shares one surrounding space), one plain space goes between them: \"~~attached~~ <u>secured</u>\", as in MPEP 714 examples; none is added next to whitespace or untouched punctuation, or for a pure insertion or deletion. Existing underline and strike are kept. `all` converts every revision, `at` one revision (`revision:7`) or those in the listed body paragraphs, `author` those of one author. Settles revisions, so it writes none of its own in either change mode.",
	"text.insert":                    "Insert `with` at an insertion point: just before or after the selected text, or at the start (`before`) or end (`after`) of the paragraph when `select` is omitted. Tracked: w:ins. Direct: inserted, no revision.",
	"table.delete":                   "Delete the table. Tracked: every row a tracked deletion. Direct: removed, no revision.",
	"row.insert":                     "Insert `count` rows before or after the row `at`. With `as`, the rows are the group `$<as>`. Tracked: a row insertion or deletion (w:trPr/w:ins|w:del, deleted cell content; the author's own inserted rows go outright). Direct: applied, no revision.",
	"row.delete":                     "Delete `count` rows from the row `at`. Tracked: a row insertion or deletion (w:trPr/w:ins|w:del, deleted cell content; the author's own inserted rows go outright). Direct: applied, no revision.",
	"column.insert":                  "Insert `count` columns before or after the column `at` (`table:1/column:2`). Refused in track mode: Word does not track it. Direct only.",
	"column.delete":                  "Delete `count` columns from the column `at`. Refused in track mode: Word does not track it. Direct only.",
	"cell.merge":                     "Merge a `row_span` × `column_span` block, counted in grid rows and columns, whose top left cell is `at` (the cell's position in its row, as read shows it). Refused in track mode: Word does not track it. Direct only.",
	"cell.split":                     "Split the merged cell `at`. Refused in track mode: Word does not track it. Direct only.",
	"revision.accept":                "Accept revisions: one (`at: \"revision:7\"`), all of them (`all`), or those of the listed body paragraphs (`at` a paragraph list: their content, paragraph mark and property changes, their text boxes' included; not row, cell or table changes); `author` narrows `all` or the paragraphs to that author's revisions. Accepting a paragraph mark's revision can join the paragraph with the next one. Settles revisions in both change modes; it writes none.",
	"revision.reject":                "Reject revisions: one (`at: \"revision:7\"`), all of them (`all`), or those of the listed body paragraphs (`at` a paragraph list: their content, paragraph mark and property changes, their text boxes' included; not row, cell or table changes); `author` narrows `all` or the paragraphs to that author's revisions. Rejecting a paragraph mark's revision can join the paragraph with the next one. Settles revisions in both change modes; it writes none.",
}
